<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Bouncing Ball Physics Playground</title>
  <style>
    /* Reset and Modern Styling */
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      background-color: #0b0f19;
      color: #f1f5f9;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
      overflow-x: hidden;
      padding: 20px;
    }

    /* Container layout */
    .playground-container {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 20px;
      width: 100%;
      max-width: 650px;
    }

    /* Header Styling */
    header {
      text-align: center;
      margin-bottom: 5px;
    }

    header h1 {
      font-size: 1.8rem;
      font-weight: 800;
      letter-spacing: -0.025em;
      background: linear-gradient(to right, #818cf8, #c084fc);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      margin-bottom: 6px;
    }

    header p {
      font-size: 0.9rem;
      color: #94a3b8;
    }

    /* Canvas styling: rendered at 500x500 CSS pixels */
    #sim {
      width: 500px;
      height: 500px;
      max-width: 100%;
      aspect-ratio: 1 / 1;
      background-color: #111827;
      border: 2px solid #374151;
      border-radius: 16px;
      box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 
                  0 0 30px rgba(99, 102, 241, 0.15);
      cursor: crosshair;
      display: block;
      transition: border-color 0.3s ease, box-shadow 0.3s ease;
    }

    #sim:hover {
      border-color: #4f46e5;
      box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.6), 
                  0 0 40px rgba(99, 102, 241, 0.25);
    }

    /* Control Panel Buttons */
    .controls {
      display: flex;
      gap: 12px;
      width: 100%;
      justify-content: center;
      flex-wrap: wrap;
    }

    .btn {
      background-color: #1f2937;
      color: #f3f4f6;
      border: 1px solid #374151;
      padding: 12px 24px;
      border-radius: 10px;
      font-weight: 600;
      font-size: 0.95rem;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
      user-select: none;
      min-width: 120px;
    }

    .btn:hover {
      background-color: #374151;
      border-color: #4b5563;
      transform: translateY(-1px);
    }

    .btn:active {
      transform: translateY(1px);
    }

    /* Specific Button Accent Styles */
    #drop {
      background: linear-gradient(135deg, #4f46e5, #4338ca);
      border-color: #6366f1;
      color: #ffffff;
      box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);
    }

    #drop:hover {
      background: linear-gradient(135deg, #6366f1, #4f46e5);
      box-shadow: 0 6px 16px rgba(79, 70, 229, 0.4);
    }

    #play {
      background-color: #065f46;
      border-color: #047857;
      color: #a7f3d0;
    }

    #play:hover {
      background-color: #047857;
      border-color: #059669;
    }

    #play.paused {
      background-color: #7f1d1d;
      border-color: #991b1b;
      color: #fca5a5;
    }

    #play.paused:hover {
      background-color: #991b1b;
      border-color: #b91c1c;
    }

    #clear {
      background-color: #111827;
      border-color: #374151;
      color: #9ca3af;
    }

    #clear:hover {
      background-color: #1f2937;
      color: #f3f4f6;
      border-color: #ef4444;
    }

    /* Stats Display */
    .stats {
      font-size: 0.85rem;
      color: #64748b;
      display: flex;
      gap: 15px;
    }

    .stats span {
      background: #1e293b;
      padding: 4px 10px;
      border-radius: 6px;
      border: 1px solid #334155;
    }

    .highlight {
      color: #818cf8;
      font-weight: 600;
    }
  </style>
</head>
<body>

  <div class="playground-container">
    <header>
      <h1>PHYSICS PLAYGROUND</h1>
      <p>Click the canvas to spawn custom balls, or use the controls below</p>
    </header>

    <canvas id="sim"></canvas>

    <div class="controls">
      <button id="drop" class="btn">Drop Ball</button>
      <button id="play" class="btn">Pause</button>
      <button id="clear" class="btn">Clear All</button>
    </div>

    <div class="stats">
      <span>Balls: <span id="ball-count" class="highlight">0</span></span>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('sim');
    const ctx = canvas.getContext('2d');

    // Simulation width and height
    const width = 600;
    const height = 600;
    canvas.width = width;
    canvas.height = height;

    // Simulation State
    let ballsList = [];
    let isPlaying = true;
    let animationFrameId = null;

    // Physics parameters
    const GRAVITY = 0.4;
    const RESTITUTION = 0.82; // Kinetic energy conservation ratio upon bounce

    class Ball {
      constructor(x, y, vx = 0, vy = 0, r = 15, color = null) {
        this.x = x;
        this.y = y;
        this.vx = vx;
        this.vy = vy;
        this.r = r;
        this.color = color || `hsl(${Math.random() * 360}, 85%, 60%)`;
        this.history = []; // Keep a short history for trailing effects
      }

      updateHistory() {
        this.history.push({ x: this.x, y: this.y });
        if (this.history.length > 8) {
          this.history.shift();
        }
      }
    }

    // Update simulation stats UI
    function updateStatsUI() {
      document.getElementById('ball-count').textContent = ballsList.length;
    }

    // Core Physics Update
    function updatePhysics(dt) {
      for (let ball of ballsList) {
        // Record current position for trail
        ball.updateHistory();

        // Apply gravity acceleration
        ball.vy += GRAVITY * dt;

        // Advance position
        ball.x += ball.vx * dt;
        ball.y += ball.vy * dt;

        // Bounce Left Edge
        if (ball.x - ball.r < 0) {
          ball.x = ball.r;
          ball.vx = -ball.vx * RESTITUTION;
        }
        // Bounce Right Edge
        else if (ball.x + ball.r > width) {
          ball.x = width - ball.r;
          ball.vx = -ball.vx * RESTITUTION;
        }

        // Bounce Top Edge
        if (ball.y - ball.r < 0) {
          ball.y = ball.r;
          ball.vy = -ball.vy * RESTITUTION;
        }
        // Bounce Bottom Edge
        else if (ball.y + ball.r > height) {
          ball.y = height - ball.r;
          ball.vy = -ball.vy * RESTITUTION;
        }
      }
    }

    // Render loop
    function draw() {
      ctx.clearRect(0, 0, width, height);

      // Draw subtle background grid lines
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.025)';
      ctx.lineWidth = 1;
      for (let x = 50; x < width; x += 50) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }
      for (let y = 50; y < height; y += 50) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      // Draw all balls
      for (let ball of ballsList) {
        // Draw trailing ghost balls
        for (let i = 0; i < ball.history.length; i++) {
          const pos = ball.history[i];
          const opacity = ((i + 1) / ball.history.length) * 0.25;
          ctx.beginPath();
          ctx.arc(pos.x, pos.y, ball.r * (0.4 + 0.6 * (i / ball.history.length)), 0, Math.PI * 2);
          ctx.fillStyle = ball.color;
          ctx.globalAlpha = opacity;
          ctx.fill();
        }
        ctx.globalAlpha = 1.0;

        // Draw main ball
        ctx.save();
        ctx.beginPath();
        ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
        ctx.fillStyle = ball.color;

        // Add neon glow
        ctx.shadowBlur = 12;
        ctx.shadowColor = ball.color;
        ctx.fill();
        ctx.restore();

        // Highlighting shine overlay for depth
        ctx.beginPath();
        ctx.arc(ball.x - ball.r * 0.3, ball.y - ball.r * 0.3, ball.r * 0.18, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.fill();
      }
    }

    // Programmatic API setup
    window.sim = {
      w: width,
      h: height,
      balls() {
        return ballsList.map(b => ({
          x: b.x,
          y: b.y,
          vx: b.vx,
          vy: b.vy,
          r: b.r
        }));
      },
      addBall(x, y, vx = 0, vy = 0, r) {
        const radius = r !== undefined ? r : 15;
        const ball = new Ball(x, y, vx, vy, radius);
        ballsList.push(ball);
        draw();
        updateStatsUI();
        return ball;
      },
      clear() {
        ballsList = [];
        draw();
        updateStatsUI();
      },
      step(dt = 1) {
        updatePhysics(dt);
        draw();
      }
    };

    // Animation frames controller
    function loop() {
      if (isPlaying) {
        window.sim.step(1);
      }
      animationFrameId = requestAnimationFrame(loop);
    }

    // UI Interactive Event Listeners

    // Clicking the canvas spawns a ball with dynamic kick direction
    canvas.addEventListener('click', (e) => {
      const rect = canvas.getBoundingClientRect();
      const scaleX = width / rect.width;
      const scaleY = height / rect.height;
      const x = (e.clientX - rect.left) * scaleX;
      const y = (e.clientY - rect.top) * scaleY;

      // Add with satisfying initial random momentum
      const vx = (Math.random() - 0.5) * 14;
      const vy = (Math.random() - 0.5) * 10 - 4;
      const r = 10 + Math.random() * 15;

      window.sim.addBall(x, y, vx, vy, r);
    });

    // Control: Drop Button
    document.getElementById('drop').addEventListener('click', () => {
      const x = width / 2;
      const y = 40;
      const vx = (Math.random() - 0.5) * 12;
      const vy = 1;
      const r = 12 + Math.random() * 14;
      window.sim.addBall(x, y, vx, vy, r);
    });

    // Control: Play/Pause Button
    const playBtn = document.getElementById('play');
    playBtn.addEventListener('click', () => {
      isPlaying = !isPlaying;
      if (isPlaying) {
        playBtn.textContent = 'Pause';
        playBtn.classList.remove('paused');
      } else {
        playBtn.textContent = 'Play';
        playBtn.classList.add('paused');
      }
    });

    // Control: Clear Button
    document.getElementById('clear').addEventListener('click', () => {
      window.sim.clear();
    });

    // Spawn 3 initial balls for aesthetic preview
    window.sim.addBall(150, 150, 4, 2, 22);
    window.sim.addBall(300, 100, -5, 1, 15);
    window.sim.addBall(450, 200, 3, -3, 18);

    // Run animation loop
    loop();
  </script>
</body>
</html>
